const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to mask clouds in Landsat 8/9 Collection 2
function maskL8sr(image) {
  // Bits 3 (cloud shadow) and 5 (cloud) are set.
  const cloudShadowBitMask = (1 << 3);
  const cloudsBitMask = (1 << 5);
  // Get the pixel QA band.
  const qa = image.select('QA_PIXEL');
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
  // Apply a scale factor to the thermal band and convert to Celsius.
  const tempC = image.select('ST_B10').multiply(0.00341802).add(149.0).subtract(273.15);
  return image.addBands(tempC, null, true).updateMask(mask);
}

async function runAnalysis() {
  // --- 1. Geometry & Time Definitions ---
  // The question asks about a future date (Aug 6, 2024). As we cannot predict the future,
  // we will analyze the same date from the most recent available year, 2023.
  const date = '2023-08-06';
  const startDate = ee.Date(date).advance(-3, 'day'); // Widen date range to increase chance of clear image
  const endDate = ee.Date(date).advance(3, 'day');

  // Define Areas of Interest (buffered points for better regional average)
  const arcDeTriomphe = ee.Geometry.Point(2.2950, 48.8738).buffer(500);
  const versailles = ee.Geometry.Point(2.1204, 48.8049).buffer(500);

  // --- 2. Data Acquisition & Check ---
  let collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(arcDeTriomphe.union(versailles));

  if (collection.size().getInfo() === 0) {
      console.log("No Landsat 9 images found for early August 2023. Trying Landsat 8.");
      collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
          .filterDate(startDate, endDate)
          .filterBounds(arcDeTriomphe.union(versailles));
  }

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
      console.log(`No Landsat 8/9 images found for ${startDate.format('YYYY-MM-dd').getInfo()} to ${endDate.format('YYYY-MM-dd').getInfo()}.`);
      console.log('A: No');
      return;
  }
  console.log(`Found ${imageCount} image(s) for the period.`);

  // --- 3. Processing ---
  const image = collection.map(maskL8sr).mosaic();

  // --- 4. Calculation ---
  const scale = 30; // Native resolution of Landsat
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const arcTempStats = image.select(['ST_B10']).reduceRegion({
    reducer: reducer,
    geometry: arcDeTriomphe,
    scale: scale,
    maxPixels: 1e9
  });

  const verTempStats = image.select(['ST_B10']).reduceRegion({
    reducer: reducer,
    geometry: versailles,
    scale: scale,
    maxPixels: 1e9
  });

  const arcTemp = arcTempStats.get('ST_B10_mean').getInfo();
  const arcPixels = arcTempStats.get('ST_B10_count').getInfo();

  const verTemp = verTempStats.get('ST_B10_mean').getInfo();
  const verPixels = verTempStats.get('ST_B10_count').getInfo();

  // --- 5. Validation & Final Answer ---
  if (arcPixels === 0 || verPixels === 0) {
      console.log(`Arc de Triomphe valid pixels: ${arcPixels}`);
      console.log(`Versailles valid pixels: ${verPixels}`);
      console.log("No valid (cloud-free) pixels in one or both locations.");
      console.log('C2: No Valid Pixels');
      return;
  }

  if (arcTemp === null || verTemp === null) {
      console.log(`Arc de Triomphe Temperature: ${arcTemp}`);
      console.log(`Versailles Temperature: ${verTemp}`);
      console.log("Calculation failed, resulted in null value.");
      console.log('C3: Calculation Failure');
      return;
  }

  const tempDifference = arcTemp - verTemp;

  console.log(`Analysis for early August 2023 (proxy for 2024).`);
  console.log(`Arc de Triomphe Temp (C): ${arcTemp.toFixed(2)} (${arcPixels} pixels)`);
  console.log(`Versailles Temp (C): ${verTemp.toFixed(2)} (${verPixels} pixels)`);
  console.log(`Temperature Difference (Arc - Versailles): ${tempDifference.toFixed(2)} C`);

  if (tempDifference >= 5) {
      console.log('A: Yes');
  } else {
      console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
  console.error(err);
  console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
});
